SELECT * FROM crm_event_registration
WHERE tenant_id = #{tenantId} AND event_id = #{eventId}
  AND session_id = #{sessionId} AND audience_key = #{audienceKey}
  AND registration_status IN ('confirmed', 'waitlist')
LIMIT 1

SELECT COUNT(DISTINCT audience_key) FROM crm_event_registration
WHERE tenant_id = #{tenantId} AND event_id = #{eventId}
  AND registration_status = 'confirmed'
  AND registration_source <> 'market_event'

    AND session_id = #{sessionId}

SELECT COUNT(DISTINCT audience_key) FROM crm_event_registration
WHERE tenant_id = #{tenantId} AND event_id = #{eventId}
  AND registration_status = 'waitlist'
  AND registration_source <> 'market_event'

    AND session_id = #{sessionId}

